pub(crate) fn memory_face(
        data: &[u8],
        face_index: usize,
        size_pt: f32,
    ) -> Result<Self, FontError> {
        if read_u32_le(data, 0) == Some(PCF_FILE_VERSION) {
            return Self::pcf_face(data, face_index, size_pt);
        }
        if data.starts_with(b"PFR0") {
            return Self::pfr_face(data, face_index, size_pt);
        }
        if matches!(read_u16_le(data, 0), Some(0x0200) | Some(0x0300)) {
            return Self::winfnt_face(data, face_index, size_pt);
        }
        if bdf_text(data)
            .and_then(first_bdf_keyword)
            .is_some_and(is_bdf_probe_keyword)
        {
            if let Some(error) = parse_bdf_constructor_error(data) {
                return Err(error);
            }
            return Self::bdf_face(data, face_index, size_pt);
        }
        if data.starts_with(b"%!PS-Adobe-3.0 Resource-CIDFont") {
            return Self::cid_type1_face(data, face_index, size_pt);
        }

if type42_sfnt_data(data).is_some() {
    return Self::type42_face(data, face_index, size_pt);
}
if type1_cleartext(data).is_some() {
    return Self::type1_face(data, face_index, size_pt);
}
if data.len() >= 17 && data.iter().all(|byte| *byte < b' ') {
    // FreeType's final BDF driver probe (`bdf/bdflib.c`) skips every
    // byte below ASCII space while looking for a line.  An all-
    // control stream therefore reaches EOF with no `STARTFONT`
    // line and returns Invalid_File_Format from `bdf_load_font`;
    // `BDF_Face_Init` preserves that error for `FT_Open_Face`.
    // Keep the length guard because earlier C driver probes use
    // fixed-size frames and win the error race on shorter streams.
    return Err(FontError::InvalidFileFormat(
        "BDF stream ended before a complete line".into(),
    ));
}

    match Self::truetype_face(data, face_index, size_pt) {
        Ok(face) => Ok(face),
        Err(error) if data.len() >= 118 => {
            // FreeType's WinFNT driver tries a standalone FNT header
            // after its MZ/NE probe fails. Its unknown-format result is
            // the final face-open error for a structurally plausible FNT
            // header with an unsupported version; unrelated malformed
            // buffers retain the earlier SFNT parser error.
            match Self::winfnt_face(data, face_index, size_pt) {
                Ok(face) => Ok(face),
                Err(FontError::UnknownFileFormat(message)) if has_winfnt_header_shape(data) => {
                    Err(FontError::UnknownFileFormat(message))
                }
                Err(_) => Err(error),
            }
        }
        Err(error) => Err(error),
    }
}

pub fn load_glyph(&self, glyph_index: u16, flags: LoadFlags) -> Result<GlyphSlot, FontError> {
        self.load_glyph_with_transform(glyph_index, flags, None)
    }

    pub(crate) fn incremental_glyph_data(&self, glyph_index: u16) -> Option<&[u8]> {
        let data = &self.font.data;
        let location = loca::get_glyph_location(
            &data.loca_data,
            glyph_index,
            data.head.index_to_loc_format,
            data.glyf_data.len(),
        )?;
        let start = usize::try_from(location.offset).ok()?;
        let end = start.checked_add(usize::try_from(location.length).ok()?)?;
        data.glyf_data.get(start..end)
    }

    /// Load a glyph index with an optional transform, equivalent to
    /// `FT_Load_Glyph` + `FT_Set_Transform`.
    ///
    /// Matrix coefficients are signed 16.16, while the final two tuple values
    /// are 26.6 translation coordinates.
    ///
    /// # Errors
    ///

fn load_glyph_from_font(
        font: &Font,
        glyph_index: u16,
        mut flags: LoadFlags,
        transform: Option<(i32, i32, i32, i32, i32, i32)>,
    ) -> Result<GlyphSlot, FontError> {
        flags = Self::normalize_load_flags(font, flags);
        if font.sbix_active_strike_is_unmatched() {
            // `ttdriver.c:tt_size_request` retains Invalid_Pixel_Size when
            // `set_sbit_strike` cannot select a fixed sbix strike.  Model the
            // load-time result here because the public C sequence continues
            // after that setup return; all ABI facades share this guard.
            return Err(FontError::InvalidPixelSize);
        }
        let transform = if flags.contains(LoadFlags::NO_RECURSE) {
            None
        } else {
            transform
        };
        let vertical_layout = flags.contains(LoadFlags::VERTICAL_LAYOUT);
        let native_hint_mode = flags.native_hint_mode();

// Only extract render outline when we're going to render.
// Otherwise leave it in `loaded` for potential later FT_Render_Glyph calls.
let mut render_lo = if render_requested {
    loaded.render_outline.take()
} else {
    None
};

// Build the slot (without render_outline — we handle rendering below).
let mut slot = GlyphSlot::new(glyph_index, loaded, None, vertical_layout, false);

// Apply transform to slot AND extracted outline before rendering.
if let Some((xx, xy, yx, yy, dx, dy)) = transform {
    slot.apply_transform(xx, xy, yx, yy, dx, dy);
    if let Some(lo) = render_lo.as_mut() {
        transform_loaded_outline_for_render(lo, xx, xy, yx, yy, dx, dy);
    }
}

// Render without cloning the outline — takes ownership.
if render_requested {
    if let Some(lo) = render_lo {
        let mode = flags.render_mode();

            let mut scratch = font.raster_scratch.borrow_mut();
            let bmp = crate::render::render_loaded_outline(
                lo.outline,
                lo.left,
                lo.bottom,
                lo.top,
                mode,
                {
                    let metrics = font.size_metrics();
                    Some((metrics.x_ppem, metrics.y_ppem))
                },
                &mut scratch,
            )?;
            drop(scratch);
            slot.set_rendered_bitmap(bmp);
        }
    }

    Ok(slot)
}
